// Package argparse is a small command-line argument parser supporting
// boolean flags, flags with values, positional arguments and generated help.
package argparse

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
	"text/tabwriter"
)

// ErrHelp is returned by Parse when -h or --help is given.
var ErrHelp = errors.New("help requested")

type flag struct {
	name   string
	short  rune // 0 means no short form
	help   string
	kind   string // value placeholder in help; empty for boolean flags
	def    string // default shown in help
	isBool bool
	set    func(string) error
}

type positional struct {
	name     string
	help     string
	required bool
	target   *string
}

// Parser holds flag and positional argument definitions.
type Parser struct {
	name string
	desc string

	flags []*flag
	long  map[string]*flag
	short map[rune]*flag

	pos        []*positional
	restName   string
	restHelp   string
	restTarget *[]string
}

// New returns a parser for the program name with a one-line description.
func New(name, desc string) *Parser {
	return &Parser{
		name:  name,
		desc:  desc,
		long:  map[string]*flag{},
		short: map[rune]*flag{},
	}
}

func (p *Parser) add(f *flag) {
	if f.name == "" || strings.ContainsAny(f.name, "= ") || strings.HasPrefix(f.name, "-") {
		panic(fmt.Sprintf("argparse: invalid flag name %q", f.name))
	}
	if f.name == "help" || f.short == 'h' {
		panic("argparse: --help and -h are reserved")
	}
	if _, ok := p.long[f.name]; ok {
		panic("argparse: duplicate flag --" + f.name)
	}
	p.long[f.name] = f
	if f.short != 0 {
		if _, ok := p.short[f.short]; ok {
			panic("argparse: duplicate flag -" + string(f.short))
		}
		p.short[f.short] = f
	}
	p.flags = append(p.flags, f)
}

// Bool defines a boolean flag. Pass 0 as short for no short form.
func (p *Parser) Bool(name string, short rune, help string) *bool {
	v := new(bool)
	p.add(&flag{name: name, short: short, help: help, isBool: true, set: func(s string) error {
		b, err := strconv.ParseBool(s)
		if err != nil {
			return errors.New("expected true or false")
		}
		*v = b
		return nil
	}})
	return v
}

// String defines a flag taking a string value.
func (p *Parser) String(name string, short rune, def, help string) *string {
	v := new(string)
	*v = def
	p.add(&flag{name: name, short: short, help: help, kind: "string", def: strconv.Quote(def), set: func(s string) error {
		*v = s
		return nil
	}})
	if def == "" {
		p.long[name].def = ""
	}
	return v
}

// Int defines a flag taking an integer value.
func (p *Parser) Int(name string, short rune, def int, help string) *int {
	v := new(int)
	*v = def
	p.add(&flag{name: name, short: short, help: help, kind: "int", def: strconv.Itoa(def), set: func(s string) error {
		n, err := strconv.Atoi(s)
		if err != nil {
			return errors.New("expected an integer")
		}
		*v = n
		return nil
	}})
	return v
}

// Positional defines the next positional argument. Required positionals
// must be defined before optional ones.
func (p *Parser) Positional(name, help string, required bool) *string {
	if required && len(p.pos) > 0 && !p.pos[len(p.pos)-1].required {
		panic("argparse: required positional " + name + " follows an optional one")
	}
	v := new(string)
	p.pos = append(p.pos, &positional{name: name, help: help, required: required, target: v})
	return v
}

// Rest collects all positional arguments left after the defined ones.
// Without it, extra positional arguments are an error.
func (p *Parser) Rest(name, help string) *[]string {
	if p.restTarget != nil {
		panic("argparse: Rest defined twice")
	}
	p.restName, p.restHelp = name, help
	p.restTarget = new([]string)
	return p.restTarget
}

// Parse parses args, which should not include the program name
// (use os.Args[1:]). It returns ErrHelp if help was requested.
//
// Accepted forms: --name, --name=value, --name value, -n, -n=value, -n value.
// A bare "--" ends flag parsing; a bare "-" is a positional argument.
func (p *Parser) Parse(args []string) error {
	var pos []string
	for i := 0; i < len(args); i++ {
		a := args[i]
		if a == "--" {
			pos = append(pos, args[i+1:]...)
			break
		}
		if len(a) < 2 || a[0] != '-' {
			pos = append(pos, a)
			continue
		}

		body, val, hasVal := strings.Cut(a, "=")
		if body == "--help" || body == "-h" {
			return ErrHelp
		}
		var f *flag
		if strings.HasPrefix(body, "--") {
			f = p.long[body[2:]]
		} else if r := []rune(body[1:]); len(r) == 1 {
			f = p.short[r[0]]
		}
		if f == nil {
			return fmt.Errorf("unknown flag: %s", body)
		}

		if f.isBool {
			if !hasVal {
				val = "true"
			}
		} else if !hasVal {
			if i+1 >= len(args) {
				return fmt.Errorf("flag %s needs a value", body)
			}
			i++
			val = args[i]
		}
		if err := f.set(val); err != nil {
			return fmt.Errorf("invalid value %q for flag %s: %v", val, body, err)
		}
	}

	for i, d := range p.pos {
		if i < len(pos) {
			*d.target = pos[i]
		} else if d.required {
			return fmt.Errorf("missing argument: %s", d.name)
		}
	}
	if len(pos) > len(p.pos) {
		extra := pos[len(p.pos):]
		if p.restTarget == nil {
			return fmt.Errorf("unexpected argument: %s", extra[0])
		}
		*p.restTarget = extra
	}
	return nil
}

// Usage returns the help message generated from the definitions.
func (p *Parser) Usage() string {
	var b strings.Builder

	b.WriteString("Usage: " + p.name + " [flags]")
	for _, d := range p.pos {
		if d.required {
			b.WriteString(" <" + d.name + ">")
		} else {
			b.WriteString(" [" + d.name + "]")
		}
	}
	if p.restTarget != nil {
		b.WriteString(" [" + p.restName + "...]")
	}
	b.WriteString("\n")
	if p.desc != "" {
		b.WriteString("\n" + p.desc + "\n")
	}

	w := tabwriter.NewWriter(&b, 0, 0, 3, ' ', 0)
	if len(p.pos) > 0 || p.restTarget != nil {
		fmt.Fprintln(w, "\nArguments:")
		for _, d := range p.pos {
			fmt.Fprintf(w, "  %s\t%s\n", d.name, d.help)
		}
		if p.restTarget != nil {
			fmt.Fprintf(w, "  %s...\t%s\n", p.restName, p.restHelp)
		}
		w.Flush()
	}

	fmt.Fprintln(w, "\nFlags:")
	for _, f := range p.flags {
		left := "    "
		if f.short != 0 {
			left = "-" + string(f.short) + ", "
		}
		left += "--" + f.name
		if !f.isBool {
			left += " <" + f.kind + ">"
		}
		help := f.help
		if f.def != "" {
			help += " (default " + f.def + ")"
		}
		fmt.Fprintf(w, "  %s\t%s\n", left, help)
	}
	fmt.Fprintf(w, "  -h, --help\tshow this help\n")
	w.Flush()

	return b.String()
}

package argparse

import (
	"errors"
	"reflect"
	"strings"
	"testing"
)

type parsed struct {
	verbose *bool
	name    *string
	count   *int
	src     *string
	dst     *string
	rest    *[]string
}

func newParser() (*Parser, parsed) {
	p := New("copy", "Copy things.")
	return p, parsed{
		verbose: p.Bool("verbose", 'v', "verbose output"),
		name:    p.String("name", 'n', "World", "name to use"),
		count:   p.Int("count", 0, 1, "repeat count"),
		src:     p.Positional("src", "source", true),
		dst:     p.Positional("dst", "destination", false),
		rest:    p.Rest("extra", "extra paths"),
	}
}

func TestParse(t *testing.T) {
	p, v := newParser()
	err := p.Parse([]string{"-v", "a", "--name=Bob", "--count", "-3", "b", "c", "--", "-d"})
	if err != nil {
		t.Fatal(err)
	}
	if !*v.verbose || *v.name != "Bob" || *v.count != -3 || *v.src != "a" || *v.dst != "b" {
		t.Errorf("got verbose=%v name=%q count=%d src=%q dst=%q", *v.verbose, *v.name, *v.count, *v.src, *v.dst)
	}
	if want := []string{"c", "-d"}; !reflect.DeepEqual(*v.rest, want) {
		t.Errorf("rest = %q, want %q", *v.rest, want)
	}
}

func TestDefaults(t *testing.T) {
	p, v := newParser()
	if err := p.Parse([]string{"-"}); err != nil {
		t.Fatal(err)
	}
	if *v.verbose || *v.name != "World" || *v.count != 1 || *v.src != "-" || *v.dst != "" || *v.rest != nil {
		t.Errorf("unexpected defaults: %+v", v)
	}
}

func TestShortAndBoolValue(t *testing.T) {
	p, v := newParser()
	if err := p.Parse([]string{"-n", "Al", "--verbose=false", "a"}); err != nil {
		t.Fatal(err)
	}
	if *v.verbose || *v.name != "Al" {
		t.Errorf("got verbose=%v name=%q", *v.verbose, *v.name)
	}
}

func TestErrors(t *testing.T) {
	cases := []struct {
		args []string
		want string
	}{
		{[]string{}, "missing argument: src"},
		{[]string{"a", "--nope"}, "unknown flag: --nope"},
		{[]string{"a", "-vn"}, "unknown flag: -vn"},
		{[]string{"a", "--name"}, "flag --name needs a value"},
		{[]string{"a", "--count=x"}, `invalid value "x" for flag --count: expected an integer`},
		{[]string{"a", "--verbose=maybe"}, `invalid value "maybe" for flag --verbose: expected true or false`},
	}
	for _, c := range cases {
		p, _ := newParser()
		err := p.Parse(c.args)
		if err == nil || err.Error() != c.want {
			t.Errorf("Parse(%q) = %v, want %q", c.args, err, c.want)
		}
	}
}

func TestUnexpectedArgument(t *testing.T) {
	p := New("x", "")
	p.Positional("one", "", true)
	err := p.Parse([]string{"a", "b"})
	if err == nil || err.Error() != "unexpected argument: b" {
		t.Errorf("got %v", err)
	}
}

func TestHelp(t *testing.T) {
	p, _ := newParser()
	for _, a := range []string{"-h", "--help"} {
		if err := p.Parse([]string{a}); !errors.Is(err, ErrHelp) {
			t.Errorf("Parse(%s) = %v, want ErrHelp", a, err)
		}
	}
	want := strings.TrimLeft(`
Usage: copy [flags] <src> [dst] [extra...]

Copy things.

Arguments:
  src        source
  dst        destination
  extra...   extra paths

Flags:
  -v, --verbose         verbose output
  -n, --name <string>   name to use (default "World")
      --count <int>     repeat count (default 1)
  -h, --help            show this help
`, "\n")
	if got := p.Usage(); got != want {
		t.Errorf("Usage() =\n%s\nwant\n%s", got, want)
	}
}

package main

import (
	"errors"
	"fmt"
	"os"

	"argparse"
)

func main() {
	p := argparse.New("greet", "Print a greeting to each listed person.")
	shout := p.Bool("shout", 's', "end the greeting with an exclamation mark")
	greeting := p.String("greeting", 'g', "Hello", "greeting word")
	count := p.Int("count", 'c', 1, "times to repeat each greeting")
	first := p.Positional("name", "person to greet", true)
	others := p.Rest("others", "more people to greet")

	if err := p.Parse(os.Args[1:]); err != nil {
		if errors.Is(err, argparse.ErrHelp) {
			fmt.Print(p.Usage())
			return
		}
		fmt.Fprintf(os.Stderr, "greet: %v\n\n%s", err, p.Usage())
		os.Exit(2)
	}

	end := "."
	if *shout {
		end = "!"
	}
	for _, name := range append([]string{*first}, *others...) {
		for i := 0; i < *count; i++ {
			fmt.Printf("%s, %s%s\n", *greeting, name, end)
		}
	}
}

